mapper.select:
SELECT id, name, content_type, display_order, is_visible
FROM info_categories
WHERE id = #{id}

mapper.update:
UPDATE info_categories
SET name = #{name},
    content_type = #{contentType},
    display_order = #{displayOrder},
    is_visible = #{isVisible}
WHERE id = #{id}

mapper.select:
SELECT COUNT(*)
FROM info_categories
WHERE name = #{name}

    AND id <> #{excludeId}

SELECT COUNT(*)
FROM travel_info
WHERE category_id = #{categoryId}

mapper.update:
UPDATE info_category_translations
SET name = #{name}
WHERE info_category_id = #{infoCategoryId}
  AND language_code = #{languageCode}

mapper.delete:
DELETE FROM info_category_translations
WHERE info_category_id = #{infoCategoryId}
  AND language_code = #{languageCode}
